  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function isPrimitive(value) {
  return value === null
    || typeof value === 'string'
    || typeof value === 'number'
    || typeof value === 'boolean';
}

function assertConfigObject(value, name) {
  if (!isPlainObject(value)) {
    throw new TypeError(`${name} must be a non-null, non-array plain object`);
  }
}

function assertValue(value, name) {
  if (isPrimitive(value)) {
    return;
  }
  if (isPlainObject(value)) {
    for (const key of Object.keys(value)) {
      if (!isPrimitive(value[key])) {
        throw new TypeError(`${name}.${key} must be a primitive`);
      }
    }
    return;
  }
  throw new TypeError(`${name} must be a primitive or a one-level plain object`);
}

function cloneNested(source) {
  const target = {};
  for (const key of Object.keys(source)) {
    target[key] = source[key];
  }
  return target;
}

export function mergeConfig(defaults, overrides = {}) {
  assertConfigObject(defaults, 'defaults');
  assertConfigObject(overrides, 'overrides');

  const result = {};

  for (const key of Object.keys(defaults)) {
    const value = defaults[key];
    assertValue(value, `defaults.${key}`);
    result[key] = isPlainObject(value) ? cloneNested(value) : value;
  }

  for (const key of Object.keys(overrides)) {
    const value = overrides[key];
    assertValue(value, `overrides.${key}`);

    const existing = Object.prototype.hasOwnProperty.call(result, key)
      ? result[key]
      : undefined;

    if (isPlainObject(value) && isPlainObject(existing)) {
      const merged = cloneNested(existing);
      for (const nestedKey of Object.keys(value)) {
        merged[nestedKey] = value[nestedKey];
      }
      result[key] = merged;
    } else if (isPlainObject(value)) {
      result[key] = cloneNested(value);
    } else {
      result[key] = value;
    }
  }

  return result;
}
